import re
from typing import List, Dict, Any, Tuple, Optional

# ----------------------------------------------------------------------
# Helpers (assumed to be provided in the sandbox)
# ----------------------------------------------------------------------
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of node dicts
# scope_nodes(doc, scope) -> list of node dicts that belong to the scope
# table_rows(node) -> list of tuples (row_index, {column: cell_str})
# ----------------------------------------------------------------------


# ----------------------------------------------------------------------
# Utility functions
# ----------------------------------------------------------------------
def _split_object_description(line: str) -> Tuple[str, str]:
    """
    Parses a line from an 'Objects' list node.
    For example: 'Object 0: red rubber cylinder (color=red, material=rubber, shape=cylinder)'
    Returns ('Object 0', 'red rubber cylinder (color=red, material=rubber, shape=cylinder)')
    """
    try:
        colon = line.index(':')
        obj_id = line[:colon].strip()
        description = line[colon + 1 :].strip()
        return obj_id, description
    except ValueError:
        return line.strip(), ""


def _extract_frame(line: str) -> Optional[float]:
    """
    Extracts the frame number from a line that starts with 'Frame X:'.
    """
    m = re.match(r"\s*Frame\s+(\d+):", line)
    return float(m.group(1)) if m else None


def _extract_entities_from_event(line: str) -> List[str]:
    """
    Returns a list of entity ids mentioned in the event line.
    The ids are of the form 'Object 0'.
    """
    return re.findall(r"Object\s+\d+", line)


def _extract_event_kind(line: str) -> Optional[str]:
    """
    Returns a simplified kind code depending on the verb in the event line.
    """
    if "enters" in line:
        return "arrival"
    if "exits" in line:
        return "exit"
    if "collides" in line:
        return "collision"
    return None


def _object_id_from_motion_obj(col: str) -> str:
    """
    Given the 'object' column string from a motion log row (e.g. '1 blue rubber sphere'),
    extract the object id 'Object 1'.
    """
    parts = col.strip().split()
    if parts:
        return f"Object {parts[0]}"
    return f"Object {col.strip()}"


def _row_location(node_id: str, row_index: int, columns: List[str] = None) -> List[Any]:
    """
    Returns the src representation for a table row.
    If columns are given, location references those cells; otherwise the whole row.
    """
    if columns is None:
        return [node_id, row_index]
    else:
        return [node_id, row_index, columns]


# ----------------------------------------------------------------------
# Main interface functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return list of distinct entities in the scope."""
    ents = []
    obj_list_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            obj_list_node = node
            break
    if not obj_list_node:
        return ents
    for line in obj_list_node.get("lines", []):
        ent_id, description = _split_object_description(line)
        ents.append({"id": ent_id, "description": description})
    return ents


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last time point covered by the scope's records."""
    last = None
    # Search events
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line in node.get("lines", []):
                frame = _extract_frame(line)
                if frame is not None and (last is None or frame > last):
                    last = frame
        # Search motion log
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            for row_index, row in table_rows(node):
                frame = float(row.get("frame", 0))
                if last is None or frame > last:
                    last = frame
    return last


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all input records for the scope."""
    results: List[Dict[str, Any]] = []
    # Map from object id to first appearance in motion log
    first_record: Dict[str, Tuple[float, Dict[str, Any], int]] = {}

    # Gather first motion log record per object
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            break
    if motion_node:
        for row_index, row in table_rows(motion_node):
            obj_col = row.get("object", "")
            obj_id = _object_id_from_motion_obj(obj_col)
            frame = float(row.get("frame", 0))
            if obj_id not in first_record or frame < first_record[obj_id][0]:
                first_record[obj_id] = (frame, row, row_index)

    # Process events for arrivals and initial states
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame = _extract_frame(line)
                if frame is None:
                    continue
                kind = _extract_event_kind(line)
                entities_in_line = _extract_entities_from_event(line)
                src = [node.get("node_id"), line_index]

                if kind == "arrival":
                    for ent in entities_in_line:
                        results.append(
                            {
                                "id": f"input-{ent}-{frame}",
                                "time": frame,
                                "kind": "arrival",
                                "entities": [ent],
                                "fields": {},
                                "src": [src],
                            }
                        )

                elif kind is None:
                    # This may be an initial state line ('is in view when the video begins')
                    for ent in entities_in_line:
                        if ent in first_record:
                            frame0, row0, row_index = first_record[ent]
                            fields = {
                                "x": float(row0.get("x", 0)),
                                "y": float(row0.get("y", 0)),
                                "vx": float(row0.get("vx", 0)),
                                "vy": float(row0.get("vy", 0)),
                                "speed": float(row0.get("speed", 0)),
                            }
                            results.append(
                                {
                                    "id": f"input-{ent}-{frame}",
                                    "time": frame0,
                                    "kind": "initial",
                                    "entities": [ent],
                                    "fields": fields,
                                    "src": [_row_location(node.get("node_id"), row_index)],
                                }
                            )
                # No input for 'exit' or 'collision'

    # Additionally add initial state for objects that never appear in events but exist in motion log
    for ent, (frame0, row0, row_index) in first_record.items():
        # If already added by event processing, skip
        if any(inp["entities"] == [ent] for inp in results):
            continue
        fields = {
            "x": float(row0.get("x", 0)),
            "y": float(row0.get("y", 0)),
            "vx": float(row0.get("vx", 0)),
            "vy": float(row0.get("vy", 0)),
            "speed": float(row0.get("speed", 0)),
        }
        results.append(
            {
                "id": f"input-{ent}-{frame0}",
                "time": frame0,
                "kind": "initial",
                "entities": [ent],
                "fields": fields,
                "src": [_row_location(motion_node.get("node_id"), row_index)],
            }
        )

    return results


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcome records for the scope."""
    results: List[Dict[str, Any]] = []

    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame = _extract_frame(line)
                if frame is None:
                    continue
                kind = _extract_event_kind(line)
                entities_in_line = _extract_entities_from_event(line)
                src = [node.get("node_id"), line_index]
                if kind in {"collision", "exit"}:
                    results.append(
                        {
                            "time": frame,
                            "kind": kind,
                            "entities": entities_in_line,
                            "value": None,
                            "src": [src],
                        }
                    )
    return results


def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """Return any constant parameters present in the scope."""
    # In this domain the document does not specify global constants like limits or rates.
    # If such constants existed in a dedicated node they'd be extracted here.
    return {}


# ---- step 2: forward model ----
# Final submit
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Return collision outcomes for a CLEVRER video based on the motion log.
    The function infers collisions by pairwise distance queries.
    """
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            break
    if motion_node is None:
        return []

    frames = {}
    for row_index, row in table_rows(motion_node):
        frame = int(float(row.get("frame", 0)))
        obj_id = _object_id_from_motion_obj(row.get("object", ""))
        frames.setdefault(frame, {})[obj_id] = (float(row.get("x", 0)), float(row.get("y", 0)))

    present_objects = set()
    for inp in inputs:
        if inp["kind"] in ("arrival", "initial"):
            present_objects.add(inp["entities"][0])

    COLLISION_DISTANCE = 0.55
    reported = set()
    outcomes = []

    sorted_frames = sorted(frames.keys())
    for frame in sorted_frames:
        if start is not None and frame < start:
            continue
        if horizon is not None and frame > horizon:
            break
        objs_at_frame = frames[frame]
        active_objs = present_objects & objs_at_frame.keys()
        for a in active_objs:
            for b in active_objs:
                if a >= b:
                    continue
                pair = tuple(sorted((a, b)))
                if pair in reported:
                    continue
                pos_a = objs_at_frame[a]
                pos_b = objs_at_frame[b]
                dx = pos_a[0] - pos_b[0]
                dy = pos_a[1] - pos_b[1]
                dist = (dx * dx + dy * dy) ** 0.5
                if dist < COLLISION_DISTANCE:
                    outcomes.append(
                        {
                            "time": float(frame),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": None,
                        }
                    )
                    reported.add(pair)

    outcomes.sort(key=lambda o: o["time"])
    return outcomes

