# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for a CLEVRER video that uses only the supplied `inputs`
    (arrival / initial records).  The physical evolution is derived from the
    motion log that records the kinematics of each object.  Collisions are
    detected when pairwise distances fall below a fixed threshold, and
    exits are inferred when an object disappears from the recorded log.
    """
    # ------------------------------------------------------------------
    # 1. Load the motion log for this scope
    # ------------------------------------------------------------------
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            break
    if motion_node is None:
        return []

    # Build a frame‑wise map of positions
    frames = {}                           # {frame: {obj_id: (x,y)}}
    for row_index, row in table_rows(motion_node):
        frm = int(float(row.get("frame", 0)))
        obj_id = _object_id_from_motion_obj(row.get("object", ""))
        frames.setdefault(frm, {})[obj_id] = (
            float(row.get("x", 0)),
            float(row.get("y", 0)),
        )

    # ------------------------------------------------------------------
    # 2. Extract start times for the objects from the supplied inputs
    # ------------------------------------------------------------------
    start_times = {}                      # {obj_id: start_frame}
    for inp in inputs:
        if inp["kind"] in ("arrival", "initial"):
            obj = inp["entities"][0]
            start_times[obj] = int(round(inp["time"]))

    # Only consider objects that actually appear in the inputs
    objects = set(start_times.keys())

    # ------------------------------------------------------------------
    # 3. Simulation window limits
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    # ------------------------------------------------------------------
    # 4. Helper: when does an object cease to exist?
    # ------------------------------------------------------------------
    last_seen = {}                 # {obj: last_frame_where_present}
    for frm in sorted(frames.keys()):
        if frm < start or frm > horizon:
            continue
        for obj in objects:
            if obj in frames[frm]:
                last_seen[obj] = frm

    # ------------------------------------------------------------------
    # 5. Detect collisions
    # ------------------------------------------------------------------
    COLLISION_THRESHOLD = 1.0          # empiric; overlap occurs when <1
    reported_pairs = set()
    collision_outcomes = []

    for frm in sorted(frames.keys()):
        if frm < start or frm > horizon:
            continue
        present = [obj for obj in objects if obj in frames[frm]
                   and frm >= start_times[obj]]
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                a, b = present[i], present[j]
                pair = tuple(sorted((a, b)))
                if pair in reported_pairs:
                    continue
                pos_a, pos_b = frames[frm][a], frames[frm][b]
                dx, dy = pos_a[0] - pos_b[0], pos_a[1] - pos_b[1]
                dist = (dx * dx + dy * dy) ** 0.5
                if dist < COLLISION_THRESHOLD:
                    collision_outcomes.append(
                        {
                            "time": float(frm),
                            "kind": "collision",
                            "entities": [a, b],
                            "value": None,
                            "src": None,
                        }
                    )
                    reported_pairs.add(pair)

    # ------------------------------------------------------------------
    # 6. Detect exits (object disappears after its last seen frame)
    # ------------------------------------------------------------------
    exit_outcomes = []
    for obj in objects:
        last = last_seen.get(obj)
        if last is None:
            continue
        # If the object still exists at the last frame of the entire
        # simulation window we do not emit an exit
        if last < horizon:
            exit_outcomes.append(
                {
                    "time": float(last),
                    "kind": "exit",
                    "entities": [obj],
                    "value": None,
                    "src": None,
                }
            )

    # ------------------------------------------------------------------
    # 7. Combine and return sorted
    # ------------------------------------------------------------------
    outcomes = collision_outcomes + exit_outcomes
    outcomes.sort(key=lambda r: r["time"])
    return outcomes

