import math
def _dist_sq(a, b):
    dx, dy = a[0]-b[0], a[1]-b[1]
    return dx*dx + dy*dy

def _collision_time_between(p0, p1, q0, q1, R, t0, t1):
    d0x = p0[0]-q0[0]; d0y = p0[1]-q0[1]
    dvx = (p1[0]-p0[0])-(q1[0]-q0[0])
    dvy = (p1[1]-p0[1])-(q1[1]-q0[1])
    A = dvx*dvx + dvy*dvy
    B = 2*(d0x*dvx + d0y*dvy)
    C = d0x*d0x + d0y*d0y - R*R
    if A == 0:
        if C <= 0:
            return t0
        return None
    disc = B*B - 4*A*C
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    s1 = (-B - sqrt_disc)/(2*A)
    s2 = (-B + sqrt_disc)/(2*A)
    best = None
    for s in (s1, s2):
        if 0 <= s <= 1:
            t = t0 + s*(t1-t0)
            if best is None or t < best:
                best = t
    return best

