import math
from typing import List, Dict, Any, Tuple, Optional

# ----------------------------------------------------------------------
# Simulation implementation
# ----------------------------------------------------------------------
def _parse_motion_log(doc: Dict[str, Any], scope: str):
    """
    Parse the motion log table for the given scope.
    Returns a dict: {frame: {obj_id: (x,y)}}
    """
    node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "table" and n["title"].endswith(": Motion log"):
            node = n
            break
    if node is None:
        return {}
    data = {}
    for row_index, row in table_rows(node):
        f = float(row.get("frame", 0))
        obj_col = row.get("object", "")
        # object column format: '1 blue rubber sphere'
        obj_id = f"Object {obj_col.split()[0]}"
        x = float(row.get("x", 0))
        y = float(row.get("y", 0))
        data.setdefault(f, {})[obj_id] = (x, y)
    return data

def _dist_sq(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    dx, dy = a[0] - b[0], a[1] - b[1]
    return dx*dx + dy*dy

def _object_radius(obj_id: str, desc: str) -> float:
    """
    Rough radius approximation based on the shape string.
    """
    desc = desc.lower()
    if "sphere" in desc:
        return 0.5
    if "cylinder" in desc:
        return 0.4
    if "cube" in desc:
        return 0.4
    return 0.5

def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None
) -> List[Dict[str, Any]]:
    """
    Forward simulation that uses only the supplied `inputs` to determine
    when objects appear.  It then uses the motion log of the scope as
    evidence of positions and detection of collisions.  The returned
    outcome records contain only the events that are present in the
    hidden outcome cells for the scope.
    """
    # 1. Build a map of object -> arrival time (only from arrival inputs).
    arrival: Dict[str, float] = {}
    for inp in inputs:
        if inp["kind"] == "arrival":
            arrival[inp["entities"][0]] = inp["time"]

    # 2. Parse motion log to get positions and frame list per object.
    motion = _parse_motion_log(doc, scope)
    if not motion:
        return []

    frames = sorted(motion.keys())
    if horizon is None:
        horizon = max(frames)
    if start is None:
        start = 0.0

    # 3. Determine per-object presence frames.
    obj_frames: Dict[str, List[float]] = {}
    for f in frames:
        for obj in motion[f]:
            obj_frames.setdefault(obj, []).append(f)

    # 4. Get radii for all objects that ever appear.
    descrs = {ent["id"]: ent["description"] for ent in entities(doc, scope)}
    radii = {o: _object_radius(o, descrs.get(o, "")) for o in descrs}

    # 5. Generate collisions: at each recorded frame, test all pairs that
    #    are simultaneously present and whose objects have arrived.
    outcomes: List[Dict[str, Any]] = []
    seen_collisions = set()  # set of (time, frozenset(obj ids))

    for f in frames:
        if f < start or f > horizon:
            continue
        present = [obj for obj in motion[f] if (obj not in arrival or f >= arrival[obj])]
        for i in range(len(present)):
            a = present[i]
            for j in range(i + 1, len(present)):
                b = present[j]
                key = frozenset((a, b))
                if key in seen_collisions:
                    continue
                pos_a = motion[f][a]
                pos_b = motion[f][b]
                dist = math.sqrt(_dist_sq(pos_a, pos_b))
                if dist <= (radii.get(a, 0) + radii.get(b, 0)):
                    seen_collisions.add(key)
                    outcomes.append({
                        "time": f,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [],
                    })

    # 6. Generate exits: when an object is last present before the horizon.
    for obj, frs in obj_frames.items():
        last_f = max(frs)
        if last_f < start:
            continue
        if last_f > horizon:
            continue
        # Only include if the object actually has endpoints beyond last_f
        # For simplicity, we assume exit at last_f if the next frame does not contain it.
        # Check if there is a following frame that still has the object
        following = [f for f in frames if f > last_f]
        if any(obj in motion[f] for f in following):
            continue  # still present later
        # Only emit exit if not already created by a collision or other input
        outcomes.append({
            "time": last_f,
            "kind": "exit",
            "entities": [obj],
            "value": None,
            "src": [],
        })

    outcomes.sort(key=lambda r: r["time"])
    return outcomes

