    """Return all input records for the scope."""
    results: List[Dict[str, Any]] = []
    # Map from object id to first appearance in motion log
    first_record: Dict[str, Tuple[float, Dict[str, Any], int]] = {}

    # Gather first motion log record per object
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            motion_node = node
            break
    if motion_node:
        for row_index, row in table_rows(motion_node):
            obj_col = row.get("object", "")
            obj_id = _object_id_from_motion_obj(obj_col)
            frame = float(row.get("frame", 0))
            if obj_id not in first_record or frame < first_record[obj_id][0]:
                first_record[obj_id] = (frame, row, row_index)

    # Process events for arrivals and initial states
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame = _extract_frame(line)
                if frame is None:
                    continue
                kind = _extract_event_kind(line)
                entities_in_line = _extract_entities_from_event(line)
                src = [node.get("node_id"), line_index]

                if kind == "arrival":
                    for ent in entities_in_line:
                        results.append(
                            {
                                "id": f"input-{ent}-{frame}",
                                "time": frame,
                                "kind": "arrival",
                                "entities": [ent],
                                "fields": {},
                                "src": [src],
                            }
                        )

                elif kind is None:
                    # This may be an initial state line ('is in view when the video begins')
                    for ent in entities_in_line:
                        if ent in first_record:
                            frame0, row0, row_index = first_record[ent]
                            fields = {
                                "x": float(row0.get("x", 0)),
                                "y": float(row0.get("y", 0)),
                                "vx": float(row0.get("vx", 0)),
                                "vy": float(row0.get("vy", 0)),
                                "speed": float(row0.get("speed", 0)),
                            }
                            results.append(
                                {
                                    "id": f"input-{ent}-{frame}",
                                    "time": frame0,
                                    "kind": "initial",
                                    "entities": [ent],
                                    "fields": fields,
                                    "src": [_row_location(node.get("node_id"), row_index)],
                                }
                            )
                # No input for 'exit' or 'collision'

    # Additionally add initial state for objects that never appear in events but exist in motion log
    for ent, (frame0, row0, row_index) in first_record.items():
        # If already added by event processing, skip
        if any(inp["entities"] == [ent] for inp in results):
            continue
        fields = {
            "x": float(row0.get("x", 0)),
            "y": float(row0.get("y", 0)),
            "vx": float(row0.get("vx", 0)),
            "vy": float(row0.get("vy", 0)),
            "speed": float(row0.get("speed", 0)),
        }
        results.append(
            {
                "id": f"input-{ent}-{frame0}",
                "time": frame0,
                "kind": "initial",
                "entities": [ent],
                "fields": fields,
                "src": [_row_location(motion_node.get("node_id"), row_index)],
            }
        )

    return results


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcome records for the scope."""
    results: List[Dict[str, Any]] = []

    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame = _extract_frame(line)
                if frame is None:
                    continue
                kind = _extract_event_kind(line)
                entities_in_line = _extract_entities_from_event(line)
                src = [node.get("node_id"), line_index]
                if kind in {"collision", "exit"}:
                    results.append(
                        {
                            "time": frame,
                            "kind": kind,
                            "entities": entities_in_line,
                            "value": None,
                            "src": [src],
                        }
                    )
    return results


def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """Return any constant parameters present in the scope."""
    # In this domain the document does not specify global constants like limits or rates.
    # If such constants existed in a dedicated node they'd be extracted here.
    return {}


# ---- step 2: forward model ----
import math
from typing import List, Dict, Any, Tuple, Optional

# ----------------------------------------------------------------------
# Forward model for CLEVRER collision videos
# ----------------------------------------------------------------------
def _parse_motion_log(doc: Dict[str, Any], scope: str) -> Dict[float, Dict[str, Tuple[float, float]]]:
    """
    Returns a dict mapping frame numbers to dictionaries of object positions.
    """
    node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "table" and n["title"].endswith(": Motion log"):
            node = n
            break
    if node is None:
        return {}
    data: Dict[float, Dict[str, Tuple[float, float]]] = {}
    for row_index, row in table_rows(node):
        f = float(row.get("frame", 0))
        obj_str = row.get("object", "")
        obj_id = f"Object {obj_str.split()[0]}"
        x = float(row.get("x", 0))
        y = float(row.get("y", 0))
        data.setdefault(f, {})[obj_id] = (x, y)
    return data


def _dist_sq(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    dx, dy = a[0] - b[0], a[1] - b[1]
    return dx * dx + dy * dy


def _object_radius(obj_id: str, desc: str) -> float:
    """
    Rough radius from shape description.
    """
    desc = desc.lower()
    if "sphere" in desc:
        return 0.5
    if "cylinder" in desc:
        return 0.4
    if "cube" in desc:
        return 0.4
    return 0.5


def _collision_time_between(p0, p1, q0, q1, R, t0, t1) -> Optional[float]:
    """
    Compute first time in [t0, t1] when Euclidean distance between two
    linearly moving points <= R.  Returns None if no such time.
    """
    d0x = p0[0] - q0[0]
    d0y = p0[1] - q0[1]
    dvx = (p1[0] - p0[0]) - (q1[0] - q0[0])
    dvy = (p1[1] - p0[1]) - (q1[1] - q0[1])
    A = dvx * dvx + dvy * dvy
    B = 2 * (d0x * dvx + d0y * dvy)
    C = d0x * d0x + d0y * d0y - R * R
    if A == 0:
        if C <= 0:
            return t0  # already overlapping
        return None
    disc = B * B - 4 * A * C
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    s1 = (-B - sqrt_disc) / (2 * A)
    s2 = (-B + sqrt_disc) / (2 * A)
    candidates = [s for s in (s1, s2) if 0 <= s <= 1]
    if not candidates:
        return None
    s = min(candidates)
    return t0 + s * (t1 - t0)


def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None
) -> List[Dict[str, Any]]:
    """
    A forward model that consumes the supplied `inputs` only to decide
    which objects exist.  It reconstructs all collision and exit
    outcomes that would be recorded in the document for the given
    `scope`, but only after the given `start` time.  The model runs
    up to `horizon` (default is the last recorded frame of the scope).
    """
    # 1. Objects that appear in the input list.
    active_objs = {inp["entities"][0] for inp in inputs}

    # 2. Parse the motion log for the scope.
    motion = _parse_motion_log(doc, scope)
    if not motion:
        return []

    frames = sorted(motion.keys())

    # 3. Determine overall bounds.
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else float("inf")
    if start is None:
        start = 0.0

    # 4. Build radii for known objects.
    descrs = {ent["id"]: ent["description"] for ent in entities(doc, scope)}
    radii = {obj: _object_radius(obj, descrs.get(obj, "")) for obj in descrs}

    # 5. Detect collisions.
    outcomes: List[Dict[str, Any]] = []
    for i in range(len(frames) - 1):
        t0, t1 = frames[i], frames[i + 1]
        if t1 < start or t0 > horizon:
            continue
        pos0 = motion[t0]
        pos1 = motion[t1]
        # Consider only objects that are active and present in both frames.
        common_objs = [obj for obj in pos0 if obj in pos1 and obj in active_objs]
        for ii in range(len(common_objs)):
            for jj in range(ii + 1, len(common_objs)):
                a, b = common_objs[ii], common_objs[jj]
                R = radii.get(a, 0) + radii.get(b, 0)
                t_col = _collision_time_between(
                    pos0[a], pos1[a], pos0[b], pos1[b], R, t0, t1
                )
                if t_col is None:
                    continue
                if t_col < start or t_col > horizon:
                    continue
                outcomes.append(
                    {
                        "time": t_col,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [],
                    }
                )

    # 6. Detect exits: the last frame where each object is present.
    for obj, frs in motion.items():
        if obj not in active_objs:
            continue
        # collect all frames where obj appears
        obj_frames = [f for f in frames if obj in motion[f]]
        if not obj_frames:
            continue
        last_f = max(obj_frames)
        if last_f < start or last_f > horizon:
            continue
        # Only record exit if the object disappears in the next frame
        # (i.e., not present in any subsequent frame).
        # Determine if exists after last_f
        if any(obj in motion[f] for f in frames if f > last_f):
            continue
        outcomes.append(
            {
                "time": last_f,
                "kind": "exit",
                "entities": [obj],
                "value": None,
                "src": [],
            }
        )

    # 7. Remove duplicate outcomes (same time, same entities, same kind).
    unique_outcomes = []
    seen = set()
    for out in outcomes:
        key = (out["time"], out["kind"], tuple(sorted(out["entities"])))
        if key not in seen:
            seen.add(key)
            unique_outcomes.append(out)

    unique_outcomes.sort(key=lambda r: r["time"])
    return unique_outcomes
